'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const http = require('node:http');
const { once } = require('node:events');
const { execFileSync } = require('node:child_process');
const Module = require('node:module');
const { pathToFileURL } = require('node:url');
const crypto = require('node:crypto');
const root = '/home/jyarwood/workspace/pi-dish-m7';
const baseline = '173b11e8cf9bad3a7f2e8e44550b748cd3b4164b';
const source = '772f01be651d7d0e63f2d0f41c26f1281a7ff41d';
const req = Module.createRequire(path.join(root, 'package.json'));
const fixture = fs.mkdtempSync('/tmp/pd-m7-cwd-');
const home = path.join(fixture, 'home');
const workspace = path.join(home, 'workspace');
fs.mkdirSync(workspace, { recursive: true });
fs.mkdirSync(path.join(fixture, 'tmux'));
fs.writeFileSync(path.join(workspace, 'needle.txt'), 'isolated cwd proof\n');
fs.writeFileSync(path.join(home, '.bashrc'), '');
const env = req('./test/test-env.js').sanitizeTestEnv({ PATH: process.env.PATH, LANG: 'C.UTF-8', HOME: home, SHELL: '/bin/bash', TMPDIR: fixture, TMUX_TMPDIR: path.join(fixture, 'tmux') });
for (const key of Object.keys(process.env)) delete process.env[key];
Object.assign(process.env, env, { PI_DISH_TERMINAL: '1' });
const express = req('express');
const WebSocket = req('ws');
const terminal = req('./lib/terminal.js');
const report = { baseline, source, runtime: process.version, platform: process.platform, fixture, isolation: 'Existing sanitizeTestEnv applied to explicit PATH/LANG/HOME/SHELL/TMPDIR/TMUX_TMPDIR allowlist; loopback ephemeral HTTP/WebSocket; no root server/session discovery/provider credentials/tmux attachment', dependencies: {}, files: [], terminals: [] };
function oldBytes(file) { return execFileSync('git', ['show', `${baseline}:${file}`], { cwd: root, encoding: 'utf8', env: { ...env, HOME: home } }); }
function loadOld(file) {
  const filename = path.join(root, file);
  const m = new Module(filename, module);
  m.filename = filename;
  m.paths = Module._nodeModulePaths(path.dirname(filename));
  m._compile(oldBytes(file), filename);
  return m.exports;
}
const hash = s => crypto.createHash('sha256').update(s).digest('hex');
for (const file of ['lib/file-search.js', 'lib/file-mention.js', 'lib/git-diff.js', 'lib/terminal.js', 'lib/tmux.js', 'lib/helper-values.js']) {
  const before = oldBytes(file), after = fs.readFileSync(path.join(root, file), 'utf8');
  assert.equal(after, before, `Shared actual native dependency must match accepted baseline: ${file}`);
  report.dependencies[file] = hash(after);
}
const implementations = {
  before: { file: loadOld('lib/file-handlers.js'), terminal: loadOld('lib/terminal-handlers.js') },
  after: { file: req('./lib/file-handlers.js'), terminal: req('./lib/terminal-handlers.js') },
};
const cases = [
  ['number', 42], ['boolean', true], ['object', { invalid: 'cwd' }], ['array', [workspace]],
  ['boxed-string', new String(workspace)], ['buffer-path', Buffer.from(workspace)], ['url-path', pathToFileURL(workspace)],
  ['null', null], ['absent', undefined], ['empty', ''], ['missing-path', path.join(home, 'missing')], ['valid-path', workspace],
];
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
async function until(fn) { const stop = Date.now() + 5000; while (!fn()) { assert.ok(Date.now() < stop, 'native response timeout'); await delay(10); } }
async function serve(handler) { const server = http.createServer(handler); server.listen(0, '127.0.0.1'); await once(server, 'listening'); return server; }
async function closeServer(server) { server.closeAllConnections(); await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve())); }
function normalized(value) {
  if (value && typeof value === 'object' && typeof value.snapshotId === 'string') {
    assert.match(value.snapshotId, /^[a-f0-9]{24}$/);
    return { ...value, snapshotId: '<random-valid-snapshot-id>' };
  }
  return value;
}
async function filesFor(impl, cwd) {
  const app = express();
  const handlers = impl.file.createFileHandlers({ resolveSessionCwd: () => cwd, findSessionSource: () => null });
  for (const [route, name] of [['files','searchSessionFiles'],['preview','filePreview'],['content','fileContent'],['diff','diffSummary'],['patch','diffPatch']]) app.get(`/sessions/:id/${route}`, handlers[name]);
  const server = await serve(app);
  const base = `http://127.0.0.1:${server.address().port}/sessions/isolated`;
  const routes = [
    ['absolute-completion', `/files?q=${encodeURIComponent(workspace + '/need')}`],
    ['relative-completion', '/files?q=.%2Fneed'], ['fuzzy-search', '/files?q=needle'],
    ['absolute-preview', `/preview?path=${encodeURIComponent(workspace + '/needle.txt')}`],
    ['relative-preview', '/preview?path=needle.txt'],
    ['raw-content', `/content?path=${encodeURIComponent(workspace + '/needle.txt')}`],
    ['diff-summary', '/diff'], ['uncaptured-patch', '/patch?repo=.&path=needle.txt&snapshot=000000000000000000000000'],
  ];
  const results = {};
  try {
    for (const [name, route] of routes) {
      const res = await fetch(base + route); const text = await res.text();
      let body; try { body = normalized(JSON.parse(text)); } catch { body = text; }
      results[name] = { status: res.status, type: res.headers.get('content-type'), body };
    }
  } finally { await closeServer(server); }
  const absolute = results['absolute-completion'];
  assert.equal(absolute.status, 200);
  assert.ok(absolute.body.files.some(item => item.path === workspace + '/needle.txt'), 'Absolute completion must survive malformed truthy cwd without coercing it');
  return results;
}
async function terminalFor(impl, cwd, id) {
  assert.equal(terminal.isTerminalAvailable(), true, 'native node-pty required, not skipped');
  const handlers = impl.terminal.createTerminalHandlers({
    upgradeAuthorized: () => true, getRegisteredSession: () => ({}), getRPCSession: () => null,
    findSessionFile: () => null, resolveSessionCwd: () => cwd, locatePiPane: async () => null,
  });
  const server = await serve((_request, response) => response.end());
  server.on('upgrade', (request, socket, head) => handlers.upgrade(request, socket, head, new URL(request.url, 'http://localhost')));
  const ws = new WebSocket(`ws://127.0.0.1:${server.address().port}/api/sessions/${id}/terminal`);
  const frames = []; let closed = null;
  ws.on('message', raw => frames.push(JSON.parse(raw.toString())));
  ws.on('close', (code, reason) => { closed = { code, reason: reason.toString() }; });
  try {
    await once(ws, 'open');
    await until(() => frames.some(frame => frame.type === 'attach' || frame.type === 'error') || closed);
    const error = frames.find(frame => frame.type === 'error');
    if (error) { await until(() => closed); return { error, closed }; }
    const attach = frames.find(frame => frame.type === 'attach');
    assert.ok(attach, 'native PTY attach frame required');
    ws.send(JSON.stringify({ type: 'input', data: "printf '\\nCWD_NATIVE_%s_DONE\\n' \"$PWD\"\r" }));
    const expected = `CWD_NATIVE_${attach.cwd}_DONE`;
    await until(() => frames.filter(frame => frame.type === 'output').map(frame => frame.data).join('').includes(expected));
    return { attach: { type: attach.type, cwd: attach.cwd }, nativePwd: attach.cwd, nativeMarkerObserved: true };
  } finally {
    if (ws.readyState !== WebSocket.CLOSED) { ws.close(); await until(() => closed); }
    const term = terminal._terminals.get(id);
    handlers.shutdown();
    if (term) await until(() => term.exited);
    assert.equal(terminal._terminals.size, 0);
    await closeServer(server);
  }
}
(async () => {
  try {
    for (const [name, cwd] of cases) {
      const before = await filesFor(implementations.before, cwd), after = await filesFor(implementations.after, cwd);
      assert.deepEqual(after, before, `file consumer/native parity: ${name}`);
      report.files.push({ name, before, after, equal: true });
      const terminalBefore = await terminalFor(implementations.before, cwd, `before-${name}`);
      const terminalAfter = await terminalFor(implementations.after, cwd, `after-${name}`);
      assert.deepEqual(terminalAfter, terminalBefore, `terminal consumer/native parity: ${name}`);
      report.terminals.push({ name, before: terminalBefore, after: terminalAfter, equal: true });
    }
    report.result = 'PASS';
  } finally {
    terminal.killAllTerminals();
    req('./lib/file-search.js').resetCaches();
    fs.rmSync(fixture, { recursive: true, force: true });
    report.cleanup = { fixtureRemoved: !fs.existsSync(fixture), terminalPoolSize: terminal._terminals.size };
    fs.writeFileSync('/tmp/pi-dish-m7-cwd-compatibility-result.json', JSON.stringify(report, null, 2) + '\n');
  }
  console.log(JSON.stringify({ result: report.result, runtime: report.runtime, fileCases: report.files.length, fileRequestsPerSide: report.files.length * 8, terminalCasesPerSide: report.terminals.length, cleanup: report.cleanup }));
})().catch(error => { console.error(error); process.exitCode = 1; });
